/bin/bash -lc "python - <<'PY'
import sim, numpy as np
# Evaluate whether a simple hold posture keeps the box from dropping after movement.
# Using m1 move until x>=0.13, then different holds.
move = {2:-60,7:-60,3:20,8:20,4:-20,9:-20,10:10}
for holdname, hold in {'zero':{}, 'home':None, 'torso5':{10:5}, 'lean':{2:-20,7:-20,3:5,8:5,4:-5,9:-5,10:5}}.items():
    s=sim.Sim()
    for t in range(200):
        for i in range(s.model.nu): s.data.ctrl[i]=0
        for idx,v in move.items(): s.data.ctrl[idx]=v
        s.step(1)
        if s.pelvis_position()[0] >= 0.13:
            break
    if hold is None:
        h = s.home_ctrl()
        for t in range(300):
            s.data.ctrl[:] = h
            s.step(1)
    else:
        for t in range(300):
            for i in range(s.model.nu): s.data.ctrl[i]=0
            for idx,v in hold.items(): s.data.ctrl[idx]=v
            s.step(1)
    print(holdname, 'pelvis', np.round(s.pelvis_position(),3), 'box', np.round(s.box_position(),3), 'upr', round(s.torso_up(),3), 'b2p', round(s.box_distance_to_pelvis(),3))
PY"

